/* 与 jx_erff 逐字符相同的算式（同一多项式、同一次序）。 */
static inline float jx_erff9(float x, jx_erf9 E)
{
  float ax = fabsf(x);
  float ac = (ax > 4.0f) ? 4.0f : ax;
  float p, r;
  p = E.e0;
  p = p * ac + E.e1;
  p = p * ac + E.e2;
  p = p * ac + E.e3;
  p = p * ac + E.e4;
  p = p * ac + E.e5;
  p = p * ac + E.e6;
  p = p * ac + E.e7;
  p = p * ac + E.e8;
  r = ac * p;
  r = (ax >= 4.0f) ? 1.0f : r;
  return (x < 0.0f) ? -r : r;
}

/* gelu(x) = 0.5x(1+erf(x/sqrt2))，系数由调用方持有。 */
static inline float jx_gelu9(float x, jx_erf9 E)
{
  return 0.5f * x * (1.0f + jx_erff9(x * 0.70710678f, E));
}

