            }
          mean = (m0 + m1) + (m2 + m3);
          for (; c < C; c++) { mean += x->d[(size_t)(bi * C + c) * Tt + t]; }
          mean /= C;
        }
        float var = 0;
        {
          float v0 = 0.0f, v1 = 0.0f, v2 = 0.0f, v3 = 0.0f;
