/* ---------------- r123：QACC 16 输出通道并行点积 ----------------
 * accx 路径每个输出元素都要 zero.accx + rur.accx_0 一次，实测小 K 时
 * 每元素摊到 ~23 周期（[i8mm] matmul 79.2 Mcyc / 3.42M 元素）。QACC 把
 * 16 个输出通道放进 16 个 20-bit lane，读出成本摊到 16 个元素上。
 *
 * 布局：T 是**转置**权重 [组][chunk][16k][16o]（见 jx_wq_init 的 r123 段），
 * x 是激活行（nchunk*16 字节，尾部已零填充）。
 *
 * 溢出：lane 是 20-bit 有符号（±524287），单次读出最多累 32 个 k
 * （32*127*127 = 516128）。超出的部分分成多次读出，int32 相加。
 * int8×int8->int32 是精确的、int32 加法可结合 -> 与 accx 路径逐位一致。 */
static void jx_dotq16(const signed char *T, const signed char *x, int nchunk,
                      int32_t *out)
{
#if defined(JX_PIE)
  int32_t tmp[16];
  int c = 0;
  if (nchunk <= 0) { for (int i = 0; i < 16; i++) { out[i] = 0; } return; }
  while (c < nchunk)
    {
      int n = nchunk - c; if (n > 2) { n = 2; }
      jx_qacc_dot16(T + (size_t)c * 256u, x + (size_t)c * 16u, n, tmp);
      if (c == 0) { for (int i = 0; i < 16; i++) { out[i] = tmp[i]; } }
      else        { for (int i = 0; i < 16; i++) { out[i] += tmp[i]; } }
      c += n;
    }
#else
  for (int i = 0; i < 16; i++) { out[i] = 0; }
  for (int c = 0; c < nchunk; c++)
    for (int kk = 0; kk < 16; kk++)
      for (int oo = 0; oo < 16; oo++)
        out[oo] += (int32_t)T[(size_t)c * 256u + (size_t)(kk << 4) + (size_t)oo]
                 * (int32_t)x[(size_t)(c << 4) + (size_t)kk];
#endif
}
```

