#else
  for (int i = 0; i < 16; i++) { out[i] = 0; }
  for (int d = 0; d < nchunk; d++)
    for (int kk = 0; kk < 16; kk++)
      for (int oo = 0; oo < 16; oo++)
        out[oo] += (int32_t)T[(size_t)d * 256u + (size_t)(kk << 4) + (size_t)oo]
                 * (int32_t)x[(size_t)(d << 4) + (size_t)kk];
#endif
}

