  i = (long)(wq - JXWQ_TAB);
  if (i < 0 || i >= NQ_TENSORS || g_wqt_off[i] < 0) { return NULL; }
  return g_wqt + g_wqt_off[i] + (((size_t)(o0 >> 4) * (size_t)nchunk) << 8);
}

static inline int64_t jx_qacc_sxt40(uint64_t v)
