    }
  mid = (n + 1) / 2;
  g_pf_job.fn = fn; g_pf_job.arg = arg; g_pf_job.lo = mid; g_pf_job.hi = n;
  __sync_synchronize();
  g_pf_busy = 1;
  __sync_synchronize();
  sem_post(&g_pf_go);
  {
    jx_pfst_t *st = jx_pfst_get(fn);
    unsigned long _t0 = jx_pfcc(), _t1, _t2, _dw, _dwq;
    fn(arg, 0, mid);
    _t1 = jx_pfcc();
    sem_wait(&g_pf_done);
    _t2 = jx_pfcc();
    _dw  = _t1 - _t0;
